const navButtons = [...document.querySelectorAll(".nav-button")];
const views = {bookmarklets: document.getElementById("bookmarkletsView"), games: document.getElementById("gamesView"), utilities: document.getElementById("utilitiesView")};
function switchView(name) { Object.entries(views).forEach(([key, section]) => { section.hidden = key !== name; }); navButtons.forEach(button => button.classList.toggle("active", button.dataset.view === name)); if (name !== "bookmarklets") window.scrollTo({top:0,behavior:"smooth"}); }
navButtons.forEach(button => button.addEventListener("click", () => switchView(button.dataset.view)));
document.querySelectorAll("[data-view='home']").forEach(link => link.addEventListener("click", event => {event.preventDefault();switchView("bookmarklets");window.scrollTo({top:0,behavior:"smooth"});}));
document.getElementById("exploreButton").addEventListener("click", () => {switchView("bookmarklets");document.getElementById("bookmarkletsView").scrollIntoView({behavior:"smooth"});});
const grid=document.getElementById("toolGrid"), count=document.getElementById("toolCount"), search=document.getElementById("searchInput"), empty=document.getElementById("emptyState");

function renderCards() { grid.innerHTML=""; bookmarklets.forEach((item,index)=>{const card=document.createElement("article");card.className="tool-card";card.dataset.search=item.search+" "+item.name+" "+item.description;card.innerHTML=`<h3></h3><p></p><span class="category"></span><div class="card-actions"><button class="small-copy" type="button">Copy bookmarklet</button></div><p class="card-status" aria-live="polite"></p>`;card.querySelector("h3").textContent=item.name;card.querySelector("p").textContent=item.description;card.querySelector(".category").textContent=item.category;card.querySelector(".small-copy").addEventListener("click",async()=>{const ok=await copyText(item.code);card.querySelector(".card-status").textContent=ok?"Copied. Paste this into a bookmark's URL/address field.":"Copy was blocked by the browser. Try selecting the code file in the bookmarklets folder.";});grid.append(card);});filterCards(); }
function filterCards() {const q=search.value.trim().toLowerCase();let visible=0;[...grid.children].forEach(card=>{const match=(card.innerText+" "+card.dataset.search).toLowerCase().includes(q);card.hidden=!match;if(match)visible++;});empty.hidden=visible!==0;count.textContent=`${visible} ${visible===1?"bookmarklet":"bookmarklets"}`;}
search.addEventListener("input",filterCards);
async function copyText(text) {try{await navigator.clipboard.writeText(text);return true;}catch(_){const area=document.createElement("textarea");area.value=text;area.style.position="fixed";area.style.opacity="0";document.body.append(area);area.select();let ok=false;try{ok=document.execCommand("copy");}catch(_){}area.remove();return ok;}}
const featured=bookmarklets.find(x=>x.id==="page-toolkit");const copyButton=document.getElementById("copyBookmarklet"),status=document.getElementById("copyStatus");
async function copyFeatured(){const ok=await copyText(featured.code);status.textContent=ok?"Copied! Create a bookmark and paste this into its URL/address field.":"Copy was blocked. Try the Page Toolkit card below.";copyButton.textContent=ok?"Copied!":"Try copying again";setTimeout(()=>copyButton.textContent="Copy Page Toolkit",2200);}
copyButton.addEventListener("click",copyFeatured);
const dialog=document.getElementById("installDialog");document.getElementById("showInstall").addEventListener("click",()=>dialog.showModal());document.getElementById("closeInstall").addEventListener("click",()=>dialog.close());document.getElementById("copyFromDialog").addEventListener("click",copyFeatured);dialog.addEventListener("click",e=>{if(e.target===dialog)dialog.close();});
renderCards();
